export default StartRegulations;

import React, { useState, useEffect, useMemo } from 'react';
import { AppConfig, BackgroundType, PhotoSize } from '../types';
import StartSelection from './StartSelection';
import StartRegulations from './StartRegulations';
import { t } from '../services/i18n';

interface StartScreenProps {
  onStart: (config: { size: PhotoSize; background: BackgroundType; quantity: number }) => void;
  onHome: () => void;
  config: AppConfig;
}

const StartScreen: React.FC<StartScreenProps> = ({ onStart, onHome, config }) => {
  const [selectedSize, setSelectedSize] = useState<PhotoSize>(PhotoSize.SIZE_4X6);
  const [selectedBg, setSelectedBg] = useState<BackgroundType>(BackgroundType.WHITE);
  const [quantity, setQuantity] = useState<number>(8);

  useEffect(() => {
    switch (selectedSize) {
      case PhotoSize.SIZE_3X4: setQuantity(16); break;
      case PhotoSize.SIZE_5X5: setQuantity(6); break;
      case PhotoSize.SIZE_4X6: 
      default: setQuantity(8); break;
    }
  }, [selectedSize]);

  const photoTypes = useMemo(() => [
    {
      id: PhotoSize.SIZE_4X6,
      label: 'Hộ Chiếu (Passport)',
      dimensions: '4x6 cm',
      defaultBg: BackgroundType.WHITE,
      icon: (
        <svg className="w-6 h-6 md:w-8 md:h-8 text-brand-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 10h18M7 15h1m4 0h1m-7 4h12a3 3 0 003-3V8a3 3 0 00-3-3H6a3 3 0 00-3 3v8a3 3 0 003 3z"></path></svg>
      )
    },
    {
      id: PhotoSize.SIZE_3X4,
      label: 'Thẻ Căn Cước / ID',
      dimensions: '3x4 cm',
      defaultBg: BackgroundType.BLUE,
      icon: (
        <svg className="w-6 h-6 md:w-8 md:h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H5a2 2 0 00-2 2v9a2 2 0 002 2h14a2 2 0 002-2V8a2 2 0 00-2-2h-5m-4 0V5a2 2 0 114 0v1m-4 0a2 2 0 104 0m-5 8a2 2 0 100-4 2 2 0 000 4zm0 0c1.306 0 2.417.835 2.83 2M9 14a3.001 3.001 0 00-2.83 2M15 11h3m-3 4h2"></path></svg>
      )
    },
    {
      id: PhotoSize.SIZE_5X5,
      label: 'Visa Mỹ (US Visa)',
      dimensions: '5x5 cm (2x2 inch)',
      defaultBg: BackgroundType.WHITE,
      icon: (
        <svg className="w-6 h-6 md:w-8 md:h-8 text-red-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3.055 11H5a2 2 0 012 2v1a2 2 0 002 2 2 2 0 012 2v2.945M8 3.935V5.5A2.5 2.5 0 0010.5 8h.5a2 2 0 012 2 2 2 0 104 0 2 2 0 012-2h1.064M15 20.488V18a2 2 0 012-2h3.064M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg>
      )
    }
  ], []);

  const handleSizeSelect = (size: PhotoSize) => {
    setSelectedSize(size);
    const type = photoTypes.find(t => t.id === size);
    if (type) setSelectedBg(type.defaultBg);
  };

  const handleStart = () => {
    onStart({ size: selectedSize, background: selectedBg, quantity: quantity });
  };

  return (
    <div className="min-h-[100dvh] h-auto bg-gradient-to-br from-brand-50 to-indigo-50 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center p-3 md:p-6 pb-20 md:pb-6">
      <div className="absolute top-2 left-2 md:top-4 md:left-4 flex gap-3 z-20">
        <button onClick={onHome} className="px-3 py-2 md:px-4 md:py-2 bg-white/80 dark:bg-gray-800/80 backdrop-blur border border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-300 rounded-xl font-bold hover:bg-white dark:hover:bg-gray-700 hover:text-brand-600 dark:hover:text-brand-400 transition flex items-center gap-2 shadow-sm text-sm">
          <svg className="w-5 h-5 md:w-4 md:h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l-7 7m-7 7h18"></path></svg>
          <span className="hidden sm:inline">{t('btn.home', config)}</span>
        </button>
      </div>

      <div className="max-w-6xl w-full bg-white dark:bg-gray-900 rounded-2xl md:rounded-3xl shadow-2xl overflow-hidden flex flex-col md:flex-row ring-1 ring-gray-100 dark:ring-gray-800 mt-12 md:mt-0 mb-safe">
        <StartSelection 
            config={config}
            selectedSize={selectedSize}
            selectedBg={selectedBg}
            quantity={quantity}
            photoTypes={photoTypes}
            onSizeSelect={handleSizeSelect}
            onBgSelect={setSelectedBg}
            onQuantityChange={setQuantity}
            onStart={handleStart}
        />
        <StartRegulations 
            config={config}
            selectedSize={selectedSize}
            photoTypes={photoTypes}
        />
      </div>
    </div>
  );
};

export default StartScreen;

import React from 'react';
import { t } from '../services/i18n';
import { AppConfig } from '../types';

interface CaptureStatusProps {
  validationStatus: 'searching' | 'analyzing' | 'adjusting' | 'valid';
  feedbackMessage: string;
  instruction: string;
  devices: MediaDeviceInfo[];
  selectedDeviceId: string;
  onDeviceChange: (id: string) => void;
  config?: AppConfig; // Config might be passed down if needed for translation, or we rely on default
}

const CaptureStatus: React.FC<CaptureStatusProps> = ({
  validationStatus, feedbackMessage, instruction, devices, selectedDeviceId, onDeviceChange, config = { language: 'vi' } as AppConfig
}) => {

  // Helper to translate dynamic feedback if possible
  const getTranslatedFeedback = (msg: string) => {
    if (msg === 'ĐẠT CHUẨN') return t('capture.status.valid', config);
    if (msg === 'Cần điều chỉnh') return t('capture.status.adjusting', config);
    if (msg === 'Không tìm thấy mặt') return t('capture.msg.no_face', config);
    if (msg === 'Đang xử lý') return t('capture.label.processing', config);
    return msg; // Fallback to raw message if not mapped
  };

  const getTranslatedInstruction = (ins: string) => {
    if (ins === 'Giữ nguyên tư thế!') return t('capture.msg.valid', config);
    if (ins === 'Chỉnh lại tư thế') return t('capture.status.adjusting', config);
    if (ins === 'Di chuyển vào khung hình') return t('capture.msg.move_in', config);
    return ins;
  };

  return (
    <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
      <select 
        value={selectedDeviceId}
        onChange={(e) => onDeviceChange(e.target.value)}
        className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
      >
        <option value="">-- Camera --</option>
        {devices.map((device, idx) => (
          <option key={device.deviceId || idx} value={device.deviceId}>
            {device.label || `Camera ${idx + 1}`}
          </option>
        ))}
      </select>

      <div className={`
        absolute top-16 left-1/2 transform -translate-x-1/2
        px-6 py-3 rounded-xl backdrop-blur-md border-2 flex flex-col items-center gap-1 transition-all duration-300 min-w-[280px] text-center shadow-lg
        ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400 text-white scale-110' : 
          validationStatus === 'adjusting' ? 'bg-yellow-600/80 border-yellow-400 text-white' :
          validationStatus === 'analyzing' ? 'bg-brand-600/80 border-brand-400 text-white' :
          'bg-red-600/80 border-red-500 text-white'}
      `}>
        <div className="flex items-center gap-2">
           {validationStatus === 'valid' ? (
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
           ) : (
              <div className="animate-spin w-4 h-4 border-2 border-current border-t-transparent rounded-full" />
           )}
           <span className="font-bold text-sm tracking-wide uppercase">{getTranslatedFeedback(feedbackMessage)}</span>
        </div>
        <span className="text-xs font-medium opacity-90">{getTranslatedInstruction(instruction)}</span>
      </div>
    </div>
  );
};

export default CaptureStatus;

import React from 'react';
import { PhotoSize, AppConfig } from '../types';
import { t } from '../services/i18n';

interface CaptureOverlayProps {
  selectedSize: PhotoSize;
  validationStatus: string;
  aiLimitReached: boolean;
  topMarginPercent: number;
  marginText: string;
  getOverlayColor: () => string;
  config?: AppConfig;
}

const CaptureOverlay: React.FC<CaptureOverlayProps> = ({
  selectedSize, validationStatus, aiLimitReached, topMarginPercent, marginText, getOverlayColor, config = { language: 'vi' } as AppConfig
}) => {
  const isUSVisa = selectedSize === PhotoSize.SIZE_5X5;
  const is3x4 = selectedSize === PhotoSize.SIZE_3X4;
  const overlayColor = getOverlayColor();

  const getSizeLabel = () => {
     if (is3x4) return t('capture.overlay.3x4', config);
     if (isUSVisa) return t('capture.overlay.5x5', config);
     return t('capture.overlay.4x6', config);
  };

  const displayMarginText = marginText.replace('CÁCH MÉP', t('capture.margin', config));

  return (
    <div className="relative z-10 w-full h-full">
      {(validationStatus === 'searching' || validationStatus === 'analyzing') && !aiLimitReached && (
        <div className="absolute top-0 left-0 w-full h-1 bg-white/80 shadow-[0_0_15px_rgba(255,255,255,1)] animate-[scan_1.5s_ease-in-out_infinite]" />
      )}

      <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none transition-colors duration-300">
         <defs>
           <mask id="faceMask">
             <rect x="0" y="0" width="100" height="100" fill="white" />
             <ellipse cx="50" cy={topMarginPercent + 35} rx={isUSVisa ? 35 : 32} ry={isUSVisa ? 42 : 38} fill="black" />
           </mask>
         </defs>

         <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#faceMask)" />

         <line x1="50" y1="0" x2="50" y2="100" stroke={overlayColor} strokeWidth="0.2" strokeDasharray="2,2" />

         <line x1="0" y1={topMarginPercent} x2="100" y2={topMarginPercent} stroke="#fbbf24" strokeWidth="0.5" strokeDasharray="5,2" />
         <text x="50" y={topMarginPercent - 1} fill="#fbbf24" fontSize="2.5" fontWeight="bold" textAnchor="middle" style={{textShadow: '0 1px 2px black'}}>{displayMarginText}</text>

         <line x1="15" y1={topMarginPercent + 28} x2="85" y2={topMarginPercent + 28} stroke={overlayColor} strokeWidth="0.5" strokeDasharray="4,4" />

         <ellipse 
            cx="50" 
            cy={topMarginPercent + 35} 
            rx={isUSVisa ? 35 : 32} 
            ry={isUSVisa ? 42 : 38} 
            fill="none" 
            stroke={overlayColor} 
            strokeWidth={validationStatus === 'valid' ? "1" : "0.5"} 
            strokeDasharray={validationStatus === 'valid' ? "0" : "2,2"} 
         />

         <text x="50" y="95" fill="white" fontSize="3" textAnchor="middle" fontWeight="bold" style={{textShadow: '0 1px 2px black'}}>
           {getSizeLabel()}
         </text>
      </svg>
    </div>
  );
};

export default CaptureOverlay;

import React from 'react';
import { t } from '../services/i18n';
import { AppConfig } from '../types';

