          <div className="flex justify-between text-[10px] font-bold text-gray-500 uppercase tracking-widest">
            <span>{t('editor.makeup.smooth', config)}</span>
            <span className="text-purple-600 dark:text-purple-400">{settings.beauty.smoothSkin}%</span>
          </div>
          <input 
            type="range" min="0" max="100" step="20" 
            value={settings.beauty.smoothSkin} 
            onChange={(e) => onAiBeautyChange('smoothSkin', Number(e.target.value))} 
            className="w-full h-1.5 bg-purple-100 dark:bg-purple-900 rounded-lg accent-purple-600 cursor-pointer" 
          />
      </div>

      {/* 3. LIPSTICK */}
      <div className="space-y-3 pt-2 border-t border-dashed border-gray-200 dark:border-gray-700">
         <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{t('editor.makeup.lipstick', config)}</span></div>
         <div className="flex flex-wrap gap-2">
            {(config.lipstickOptions || []).map(opt => (
              <button 
                key={opt.id} 
                onClick={() => { onAiBeautyChange('lipstickColor', opt.label); if(settings.beauty.lipstickIntensity === 0) onAiBeautyChange('lipstickIntensity', 50); }} 
                className={`w-6 h-6 rounded-full border-2 transition-all shadow-sm ${settings.beauty.lipstickColor === opt.label ? 'ring-2 ring-brand-500 scale-110' : 'border-white dark:border-gray-600 hover:scale-105'}`} 
                style={{ backgroundColor: opt.hex }} 
                title={opt.label}
              ></button>
            ))}
         </div>
         <input 
            type="range" min="0" max="100" step="20" 
            value={settings.beauty.lipstickIntensity} 
            onChange={(e) => onAiBeautyChange('lipstickIntensity', Number(e.target.value))} 
            className="w-full h-1 bg-pink-100 dark:bg-pink-900 rounded-lg accent-pink-500 cursor-pointer" 
         />
      </div>

      {/* 4. BLUSH */}
      <div className="space-y-3 pt-2 border-t border-dashed border-gray-200 dark:border-gray-700">
         <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{t('editor.makeup.blush', config)}</span></div>
         <div className="flex flex-wrap gap-2">
            {(config.blushOptions || []).map(opt => (
              <button 
                key={opt.id} 
                onClick={() => { onAiBeautyChange('blushColor', opt.label); if(settings.beauty.blushIntensity === 0) onAiBeautyChange('blushIntensity', 30); }} 
                className={`w-6 h-6 rounded-full border-2 transition-all shadow-sm ${settings.beauty.blushColor === opt.label ? 'ring-2 ring-brand-500 scale-110' : 'border-white dark:border-gray-600 hover:scale-105'}`} 
                style={{ backgroundColor: opt.hex }} 
                title={opt.label}
              ></button>
            ))}
         </div>
         <input 
            type="range" min="0" max="100" step="10" 
            value={settings.beauty.blushIntensity} 
            onChange={(e) => onAiBeautyChange('blushIntensity', Number(e.target.value))} 
            className="w-full h-1 bg-orange-50 dark:bg-orange-900 rounded-lg accent-orange-300 cursor-pointer" 
         />
      </div>

      {/* 5. HAIR */}
      <div className="space-y-3 pt-2 border-t border-dashed border-gray-200 dark:border-gray-700">
         <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-gray-500 uppercase tracking-widest">{t('editor.makeup.hair', config)}</span></div>
         <div className="flex flex-wrap gap-2">
            {(config.hairColorOptions || []).map(opt => (
              <button 
                key={opt.id} 
                onClick={() => { onAiBeautyChange('hairColor', opt.label); if(opt.id !== 'original' && settings.beauty.hairVolume === 0) onAiBeautyChange('hairVolume', 20); }} 
                className={`w-6 h-6 rounded-full border-2 transition-all shadow-sm ${settings.beauty.hairColor === opt.label ? 'ring-2 ring-brand-500 scale-110' : 'border-white dark:border-gray-600 hover:scale-105'} ${opt.id === 'original' ? 'bg-gradient-to-tr from-gray-200 via-gray-400 to-gray-200' : ''}`} 
                style={opt.id !== 'original' ? { backgroundColor: opt.hex } : {}} 
                title={opt.label}
              ></button>
            ))}
         </div>
         <input 
            type="range" min="0" max="100" step="20" 
            value={settings.beauty.hairVolume} 
            onChange={(e) => onAiBeautyChange('hairVolume', Number(e.target.value))} 
            className="w-full h-1 bg-slate-100 dark:bg-gray-700 rounded-lg accent-slate-600 dark:accent-gray-400 cursor-pointer" 
         />
      </div>
    </div>
  );
};

