interface CaptureStatusProps {
  validationStatus: 'searching' | 'analyzing' | 'adjusting' | 'valid';
  feedbackMessage: string;
  instruction: string;
  devices: MediaDeviceInfo[];
  selectedDeviceId: string;
  onDeviceChange: (id: string) => void;
  config?: AppConfig; // Config might be passed down if needed for translation, or we rely on default
}

const CaptureStatus: React.FC<CaptureStatusProps> = ({
  validationStatus, feedbackMessage, instruction, devices, selectedDeviceId, onDeviceChange, config = { language: 'vi' } as AppConfig
}) => {

  // Helper to translate dynamic feedback if possible
  const getTranslatedFeedback = (msg: string) => {
    if (msg === 'ĐẠT CHUẨN') return t('capture.status.valid', config);
    if (msg === 'Cần điều chỉnh') return t('capture.status.adjusting', config);
    if (msg === 'Không tìm thấy mặt') return t('capture.msg.no_face', config);
    if (msg === 'Đang xử lý') return t('capture.label.processing', config);
    return msg; // Fallback to raw message if not mapped
  };

  const getTranslatedInstruction = (ins: string) => {
    if (ins === 'Giữ nguyên tư thế!') return t('capture.msg.valid', config);
    if (ins === 'Chỉnh lại tư thế') return t('capture.status.adjusting', config);
    if (ins === 'Di chuyển vào khung hình') return t('capture.msg.move_in', config);
    return ins;
  };

  return (
    <div className="absolute top-0 left-0 right-0 z-50 p-4 flex justify-between items-start bg-gradient-to-b from-black/80 to-transparent pb-12">
      <select 
        value={selectedDeviceId}
        onChange={(e) => onDeviceChange(e.target.value)}
        className="bg-black/50 text-white text-xs border border-gray-600 rounded px-3 py-1.5 outline-none backdrop-blur-md pointer-events-auto"
      >
        <option value="">-- Camera --</option>
        {devices.map((device, idx) => (
          <option key={device.deviceId || idx} value={device.deviceId}>
            {device.label || `Camera ${idx + 1}`}
          </option>
        ))}
        {/* Added Mobile Link Option */}
        <option value="mobile-link">{t('capture.device.mobile', config)}</option>
      </select>

      <div className={`
        absolute top-16 left-1/2 transform -translate-x-1/2
        px-6 py-3 rounded-xl backdrop-blur-md border-2 flex flex-col items-center gap-1 transition-all duration-300 min-w-[280px] text-center shadow-lg
        ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400 text-white scale-110' : 
          validationStatus === 'adjusting' ? 'bg-yellow-600/80 border-yellow-400 text-white' :
          validationStatus === 'analyzing' ? 'bg-brand-600/80 border-brand-400 text-white' :
          'bg-red-600/80 border-red-500 text-white'}
      `}>
        <div className="flex items-center gap-2">
           {validationStatus === 'valid' ? (
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
           ) : (
              <div className="animate-spin w-4 h-4 border-2 border-current border-t-transparent rounded-full" />
           )}
           <span className="font-bold text-sm tracking-wide uppercase">{getTranslatedFeedback(feedbackMessage)}</span>
        </div>
        <span className="text-xs font-medium opacity-90">{getTranslatedInstruction(instruction)}</span>
      </div>
    </div>
  );
};

export default CaptureStatus;

import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, PhotoSize } from '../types';
import { getPhotoById } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, config, selectedSize }) => {
  const [sessionId, setSessionId] = useState<string>('');
  const [qrUrl, setQrUrl] = useState<string>('');
  const pollIntervalRef = useRef<any>(null);

  // 1. Generate Session ID on Mount
  useEffect(() => {
    // Generate a short, unique ID for the session
    const sid = `mob_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
    setSessionId(sid);

    // Construct the URL that the mobile phone will open
    const baseUrl = window.location.href.split('?')[0];
    const mobileLink = `${baseUrl}?mobileSession=${sid}&size=${selectedSize}`;

    // Generate QR using the existing API service
    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=0&ecc=L`);

    return () => {
      if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
    };
  }, [selectedSize]);

  // 2. Poll for Photo Upload
  useEffect(() => {
    if (!sessionId) return;

    const checkPhoto = async () => {
      try {
        // Attempt to fetch the photo by the Session ID
        const photo = await getPhotoById(sessionId);
        if (photo && photo.dataUrl) {
          // If found, complete the process
          if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
          onPhotoReceived(photo.dataUrl);
        }
      } catch (e) {
        // Ignore 404s, just keep polling
      }
    };

    // Poll every 3 seconds
    pollIntervalRef.current = setInterval(checkPhoto, 3000);

    return () => {
      if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
    };
  }, [sessionId, onPhotoReceived]);

  return (
    <div className="absolute inset-0 z-30 bg-gray-900 flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white p-6 rounded-3xl shadow-2xl max-w-sm w-full relative overflow-hidden">
        {/* Decorative header */}
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-500 to-purple-500"></div>

        <h2 className="text-xl font-black text-gray-800 mb-2 mt-2">{t('mobile.title', config)}</h2>
        <p className="text-sm text-gray-500 mb-6">{t('mobile.desc', config)}</p>

        <div className="relative mx-auto w-48 h-48 mb-6 border-4 border-gray-100 rounded-xl overflow-hidden group">
          {qrUrl ? (
            <img src={qrUrl} alt="Scan to Link" className="w-full h-full object-contain" />
          ) : (
            <div className="w-full h-full flex items-center justify-center bg-gray-100">
              <div className="w-8 h-8 border-4 border-gray-300 border-t-brand-500 rounded-full animate-spin"></div>
            </div>
          )}
          {/* Scan overlay effect */}
          <div className="absolute inset-0 bg-gradient-to-b from-brand-500/20 to-transparent h-2 w-full animate-[scan_2s_linear_infinite] pointer-events-none"></div>
        </div>

        <div className="flex items-center justify-center gap-3 text-brand-600 bg-brand-50 py-3 px-4 rounded-xl border border-brand-100">
          <div className="w-2 h-2 bg-brand-500 rounded-full animate-pulse"></div>
          <span className="text-xs font-bold uppercase tracking-wider">{t('mobile.waiting', config)}</span>
        </div>
      </div>

      {/* Instructions */}
      <div className="mt-8 flex gap-8 text-white/60">
         <div className="flex flex-col items-center gap-2">
            <div className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center border border-white/20">1</div>
            <span className="text-xs">Mở Camera</span>
         </div>
         <div className="flex flex-col items-center gap-2">
            <div className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center border border-white/20">2</div>
            <span className="text-xs">Quét QR</span>
         </div>
         <div className="flex flex-col items-center gap-2">
            <div className="w-10 h-10 rounded-full bg-white/10 flex items-center justify-center border border-white/20">3</div>
            <span className="text-xs">Chụp & Gửi</span>
         </div>
      </div>
    </div>
  );
};

export default MobileCameraLink;

import React, { useRef, useState, useEffect } from 'react';
import { AppConfig } from '../types';
import { savePhotoToCloud } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCaptureClientProps {
  sessionId: string;
  config: AppConfig;
}

const MobileCaptureClient: React.FC<MobileCaptureClientProps> = ({ sessionId, config }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [cameraError, setCameraError] = useState('');

  // Start Camera on Mount
  useEffect(() => {
    startCamera();
    return () => stopCamera();
  }, []);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment', width: { ideal: 1920 }, height: { ideal: 1080 } } 
      });
      setStream(s);
      if (videoRef.current) {
        videoRef.current.srcObject = s;
      }
    } catch (e) {
      setCameraError('Không thể truy cập camera. Vui lòng cấp quyền.');
    }
  };

  const stopCamera = () => {
    if (stream) {
      stream.getTracks().forEach(t => t.stop());
      setStream(null);
    }
  };

  const handleCapture = () => {
    if (!videoRef.current || !canvasRef.current) return;

    const video = videoRef.current;
    const canvas = canvasRef.current;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    const ctx = canvas.getContext('2d');
    if (ctx) {
        // Mobile cameras are often mirrored or rotated, but simple drawImage usually works for upload
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        const dataUrl = canvas.toDataURL('image/jpeg', 0.9);
        setCapturedImage(dataUrl);
    }
  };

  const handleRetake = () => {
    setCapturedImage(null);
  };

  const handleUpload = async () => {
    if (!capturedImage) return;
    setIsUploading(true);

    try {
        // Upload with the SPECIFIC sessionId provided in the URL
        // This allows the desktop to find it by ID
        const result = await savePhotoToCloud({
            id: sessionId, // FORCE THE ID TO MATCH SESSION
            dataUrl: capturedImage,
            timestamp: Date.now(),
            settings: { 
                size: '4x6' as any, 
                background: 'original' as any, 
                beauty: {} as any, 
                printQuantity: 1 
            }
        });

        if (result) {
            setIsCompleted(true);
        } else {
            alert('Lỗi tải lên. Vui lòng thử lại.');
        }
    } catch (e) {
        alert('Lỗi kết nối.');
    } finally {
        setIsUploading(false);
    }
  };

  if (isCompleted) {
      return (
          <div className="h-[100dvh] bg-green-500 flex flex-col items-center justify-center text-white p-6 text-center animate-fadeIn">
              <div className="w-24 h-24 bg-white rounded-full flex items-center justify-center mb-6 shadow-xl">
                  <svg className="w-12 h-12 text-green-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
              </div>
              <h2 className="text-3xl font-black mb-2">{t('mobile.connected', config)}</h2>
              <p className="opacity-90">Bạn có thể xem ảnh trên màn hình máy tính.</p>
          </div>
      );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden">
        {/* Header */}
        <div className="absolute top-0 left-0 right-0 p-4 z-10 bg-gradient-to-b from-black/60 to-transparent">
            <h1 className="text-white font-bold text-center text-lg drop-shadow-md">{t('app.name', config)}</h1>
        </div>

        {/* Content */}
        <div className="flex-1 relative flex items-center justify-center bg-gray-900">
            {cameraError ? (
                <div className="text-white text-center p-6">
                    <p className="text-red-400 mb-4 text-4xl">📷❌</p>
                    <p>{cameraError}</p>
                </div>
            ) : capturedImage ? (
                <img src={capturedImage} className="max-h-full max-w-full object-contain" alt="Captured" />
            ) : (
                <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover" />
            )}
        </div>

        {/* Controls */}
        <div className="bg-black p-6 pb-10 flex flex-col items-center justify-center gap-4">
            {capturedImage ? (
                <div className="flex w-full gap-4">
                    <button 
                        onClick={handleRetake} 
                        disabled={isUploading}
                        className="flex-1 py-4 bg-gray-800 text-white rounded-xl font-bold active:scale-95 transition"
                    >
                        {t('mobile.btn.retake', config)}
                    </button>
                    <button 
                        onClick={handleUpload} 
                        disabled={isUploading}
                        className="flex-[2] py-4 bg-brand-600 text-white rounded-xl font-bold shadow-lg active:scale-95 transition flex items-center justify-center gap-2"
                    >
                        {isUploading && <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>}
                        {isUploading ? t('mobile.btn.uploading', config) : t('mobile.btn.use', config)}
                    </button>
                </div>
            ) : (
                <>
                    <p className="text-white/60 text-xs mb-2 uppercase tracking-widest">{t('mobile.instruction', config)}</p>
                    <button 
                        onClick={handleCapture}
                        className="w-20 h-20 rounded-full border-4 border-white bg-white/20 relative flex items-center justify-center active:scale-95 transition-transform"
                    >
                        <div className="w-16 h-16 bg-white rounded-full shadow-inner"></div>
                    </button>
                </>
            )}
        </div>

        <canvas ref={canvasRef} className="hidden" />
    </div>
  );
};

export default MobileCaptureClient;

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { getConfig } from '../services/configService';

// Sub-components
import CaptureStatus from './CaptureStatus';
import CaptureOverlay from './CaptureOverlay';
import CaptureControls from './CaptureControls';
import MobileCameraLink from './MobileCameraLink';
import { t } from '../services/i18n';

// Polyfill definitions for ImageCapture API
interface PhotoCapabilities { redEyeReduction: string; imageHeight: any; imageWidth: any; fillLightMode: string[]; }
interface PhotoSettings { fillLightMode?: string; imageHeight?: number; imageWidth?: number; redEyeReduction?: boolean; }
declare class ImageCapture {
  constructor(track: MediaStreamTrack);
  takePhoto(photoSettings?: PhotoSettings): Promise<Blob>;
  getPhotoCapabilities(): Promise<PhotoCapabilities>;
  grabFrame(): Promise<ImageBitmap>;
}

interface CameraCaptureProps {
  onCapture: (imageSrc: string) => void;
  selectedSize: PhotoSize;
  onSizeChange: (size: PhotoSize) => void;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const CameraCapture: React.FC<CameraCaptureProps> = ({ onCapture, selectedSize, onSizeChange }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string>('');
  const [countdown, setCountdown] = useState<number | null>(null);
  const [isCapturing, setIsCapturing] = useState(false);
  const [devices, setDevices] = useState<MediaDeviceInfo[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState<string>('');
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>('Đang xử lý');
  const [instruction, setInstruction] = useState<string>('');
  const [aiLimitReached, setAiLimitReached] = useState(false);
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(false);
  const hasAutoCapturedForCurrentValidRef = useRef(false);
  const isAnalyzingRef = useRef(false);
  const analysisIntervalRef = useRef<any>(null);
  const lastSpokenRef = useRef<string>('');

  // Use config for i18n
  const config = getConfig();

  const isMobileLink = selectedDeviceId === 'mobile-link';

  useEffect(() => {
    getDevices();
    if (!isMobileLink) {
        startCamera();
    }
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => { stopCamera(); if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); window.speechSynthesis.cancel(); };
  }, []);

  useEffect(() => { 
      if (selectedDeviceId && !isMobileLink) startCamera(selectedDeviceId); 
      if (isMobileLink) stopCamera();
  }, [selectedDeviceId]);

  useEffect(() => {
    if (stream && !countdown && !isCapturing && !aiLimitReached && !isMobileLink) analysisIntervalRef.current = setInterval(performAIAnalysis, 5000);
    else if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [stream, countdown, selectedSize, isCapturing, aiLimitReached, isMobileLink]); 

  useEffect(() => {
    if (validationStatus === 'valid' && isAutoCaptureEnabled && !hasAutoCapturedForCurrentValidRef.current && countdown === null && !isCapturing && !isMobileLink) {
          hasAutoCapturedForCurrentValidRef.current = true;
          setCountdown(3);
    } else if (validationStatus !== 'valid') { hasAutoCapturedForCurrentValidRef.current = false; }
  }, [validationStatus, isAutoCaptureEnabled, countdown, isCapturing, isMobileLink]);

  const speak = (text: string, force: boolean = false) => {
      if (!text || (!force && lastSpokenRef.current === text)) return;
      if (force || window.speechSynthesis.speaking) window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = config.language === 'en' ? 'en-US' : 'vi-VN'; 
      // Simplified voice selection logic
      const voices = window.speechSynthesis.getVoices();
      const voice = voices.find(v => v.lang.startsWith(utterance.lang));
      if (voice) utterance.voice = voice;

      window.speechSynthesis.speak(utterance);
      lastSpokenRef.current = text;
  };

  useEffect(() => {
     if (countdown !== null) return; 
     if (isMobileLink) return;
     if (aiLimitReached) { if (lastSpokenRef.current !== 'AI_STOP') { speak(t('capture.status.analyzing', config), true); lastSpokenRef.current = 'AI_STOP'; } return; }
     if (instruction) {
         if (validationStatus === 'valid') { if (lastSpokenRef.current !== 'ok') { speak(t('capture.msg.valid', config), true); lastSpokenRef.current = 'ok'; } } 
         else { speak(instruction); }
     }
  }, [instruction, validationStatus, countdown, aiLimitReached, isMobileLink]);

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = 2/3; 
    if (selectedSize === PhotoSize.SIZE_5X5) targetRatio = 1;
    if (selectedSize === PhotoSize.SIZE_3X4) targetRatio = 3/4;
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.65; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current || aiLimitReached) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        const analysisH = 320;
        const analysisW = Math.floor(analysisH * (crop.w / crop.h));
        canvas.width = analysisW; canvas.height = analysisH;
        ctx.save(); ctx.translate(canvas.width, 0); ctx.scale(-1, 1);
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        ctx.restore();
        if (validationStatus === 'searching') setValidationStatus('analyzing');
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.6));
        if (result.feedback === 'AI_LIMIT') { setAiLimitReached(true); setValidationStatus('valid'); setFeedbackMessage('AI TẠM NGƯNG'); return; }
        if (!result.faceDetected) { setValidationStatus('searching'); setFeedbackMessage('Không tìm thấy mặt'); setInstruction('Di chuyển vào khung hình'); }
        else if (result.isCompliant) { setValidationStatus('valid'); setFeedbackMessage('ĐẠT CHUẨN'); setInstruction(result.instruction || 'Giữ nguyên tư thế!'); }
        else { setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || 'Cần điều chỉnh'); setInstruction(result.instruction || 'Chỉnh lại tư thế'); }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getDevices = async () => {
    const all = await navigator.mediaDevices.enumerateDevices();
    const video = all.filter(d => d.kind === 'videoinput');
    setDevices(video);
    const canon = video.find(d => d.label.toLowerCase().includes('canon') || d.label.toLowerCase().includes('eos'));
    if (canon) setSelectedDeviceId(canon.deviceId);
  };

  const startCamera = async (deviceId?: string) => {
    stopCamera();
    try {
      const constraints = { video: { deviceId: deviceId ? { exact: deviceId } : undefined, width: { ideal: 3840 }, height: { ideal: 2160 } } };
      let s; try { s = await navigator.mediaDevices.getUserMedia(constraints); } catch { s = await navigator.mediaDevices.getUserMedia({ video: { deviceId: deviceId ? { exact: deviceId } : undefined, width: { ideal: 1920 }, height: { ideal: 1080 } } }); }
      setStream(s); if (videoRef.current) videoRef.current.srcObject = s;
    } catch { setError('Lỗi camera'); }
  };

  const stopCamera = () => { if (stream) { stream.getTracks().forEach(t => t.stop()); setStream(null); } };

  const captureFrame = useCallback(async () => {
    setIsCapturing(true); if (shutterAudioRef.current) { shutterAudioRef.current.currentTime = 0; shutterAudioRef.current.play().catch(() => {}); }
    if (!videoRef.current || !canvasRef.current) { setIsCapturing(false); return; }
    const video = videoRef.current; const canvas = canvasRef.current; const ctx = canvas.getContext('2d');
    let src: any = video, sw = video.videoWidth, sh = video.videoHeight;
    if (stream) {
        const track = stream.getVideoTracks()[0];
        if (track && 'ImageCapture' in window) {
            try {
                const ic = new (window as any).ImageCapture(track); const blob = await ic.takePhoto();
                const hiImg = new Image(); hiImg.src = URL.createObjectURL(blob);
                await new Promise(r => hiImg.onload = r); src = hiImg; sw = hiImg.width; sh = hiImg.height;
            } catch {}
        }
    }
    if (ctx && sw > 0) {
        const crop = getCropDimensions(sw, sh);
        canvas.width = crop.w; canvas.height = crop.h;
        ctx.translate(canvas.width, 0); ctx.scale(-1, 1); ctx.drawImage(src, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        onCapture(canvas.toDataURL('image/jpeg', 1.0));
    }
    setIsCapturing(false);
  }, [onCapture, selectedSize, stream]);

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) speak(countdown.toString(), true);
    if (countdown > 0) { const t = setTimeout(() => setCountdown(countdown - 1), 1000); return () => clearTimeout(t); }
    else if (countdown === 0) { captureFrame(); setCountdown(null); }
  }, [countdown, captureFrame]);

  const topMarginPercent = useMemo(() => selectedSize === PhotoSize.SIZE_3X4 ? 7.5 : selectedSize === PhotoSize.SIZE_5X5 ? 6 : 7, [selectedSize]);
  const marginText = useMemo(() => selectedSize === PhotoSize.SIZE_4X6 ? "CÁCH MÉP 4MM" : "CÁCH MÉP 3MM", [selectedSize]);
  const getOverlayColor = () => validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : validationStatus === 'analyzing' ? '#60a5fa' : '#ef4444';

  // --- MOBILE OPTIMIZED LAYOUT ---
  // Replaced absolute positioning with Flexbox for safe-area compatibility and no-clipping.
  return (
    <div className="flex flex-col h-[100dvh] w-full bg-gray-900 relative select-none overflow-hidden touch-none py-safe">

      {/* 1. Header Area: Status */}
      <div className="shrink-0 z-20 w-full relative">
        <CaptureStatus 
          validationStatus={validationStatus}
          feedbackMessage={feedbackMessage}
          instruction={instruction}
          devices={devices}
          selectedDeviceId={selectedDeviceId}
          onDeviceChange={setSelectedDeviceId}
          config={config}
        />
      </div>

      {/* 2. Main Content: Video Feed (Flex Grow) */}
      <div className="flex-1 flex items-center justify-center w-full relative min-h-0 py-2">
         <div className={`relative transition-all duration-300 bg-black rounded-lg overflow-hidden flex items-center justify-center border-4 h-full aspect-[2/3] md:aspect-[3/4] lg:aspect-[2/3] max-w-full max-h-full ${validationStatus === 'valid' ? 'border-green-500 shadow-[0_0_30px_rgba(34,197,94,0.6)]' : validationStatus === 'adjusting' ? 'border-yellow-400' : validationStatus === 'analyzing' ? 'border-brand-400' : 'border-red-500'}`}>
            {isMobileLink ? (
                <MobileCameraLink 
                    config={config} 
                    selectedSize={selectedSize}
                    onPhotoReceived={onCapture}
                />
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline className="absolute inset-0 w-full h-full object-cover transform -scale-x-100" />
                    <CaptureOverlay 
                        selectedSize={selectedSize}
                        validationStatus={validationStatus}
                        aiLimitReached={aiLimitReached}
                        topMarginPercent={topMarginPercent}
                        marginText={marginText}
                        getOverlayColor={getOverlayColor}
                        config={config}
                    />
                    {(countdown !== null || isCapturing) && (
                    <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 z-40 backdrop-blur-sm">
                        {isCapturing ? <><div className="w-16 h-16 border-4 border-white border-t-transparent rounded-full animate-spin mb-4" /><span className="text-white font-bold tracking-widest">{t('capture.label.processing', config)}</span></> : <span className="text-[120px] md:text-[180px] font-bold text-white animate-ping">{countdown}</span>}
                    </div>
                    )}
                </>
            )}
         </div>
      </div>

      {/* 3. Footer Area: Controls */}
      <div className="shrink-0 z-20 w-full pb-2 pt-2">
        {!isMobileLink && (
            <CaptureControls 
            isAutoCaptureEnabled={isAutoCaptureEnabled}
            validationStatus={validationStatus}
            countdown={countdown}
            isCapturing={isCapturing}
            onAutoCaptureToggle={() => setIsAutoCaptureEnabled(!isAutoCaptureEnabled)}
            onCaptureClick={() => setCountdown(3)}
            config={config}
            />
        )}
      </div>

      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={analysisCanvasRef} className="hidden" />
      <style>{`@keyframes scan { 0% { top: 0%; opacity: 0; } 10% { opacity: 1; } 90% { opacity: 1; } 100% { top: 100%; opacity: 0; } }`}</style>
    </div>
  );
};

