import React, { useState, useEffect, useRef } from 'react';
import { AppConfig, PhotoSize } from '../types';
import { getPhotoById } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  onCancel: () => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, onCancel, config, selectedSize }) => {
  const [sessionId, setSessionId] = useState<string>('');
  const [qrUrl, setQrUrl] = useState<string>('');
  const [isLinked, setIsLinked] = useState(false);
  const [pollCount, setPollCount] = useState(0);
  const pollIntervalRef = useRef<any>(null);

  // 1. Khởi tạo session ID duy nhất một lần khi mount
  useEffect(() => {
    const sid = `mob_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
    setSessionId(sid);
    console.log("Session ID created:", sid);
    return () => { if (pollIntervalRef.current) clearInterval(pollIntervalRef.current); };
  }, []);

  // 2. Cập nhật QR URL khi size thay đổi nhưng giữ nguyên Session ID
  useEffect(() => {
    if (!sessionId) return;

    const baseUrl = window.location.href.split('?')[0];
    const mobileLink = `${baseUrl}?mobileSession=${sessionId}&size=${selectedSize}`;

    // Tạo mã QR mới với kích thước ảnh đã chọn
    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=2&ecc=M`);
  }, [sessionId, selectedSize]);

  // 3. Polling kết quả từ Cloud với tốc độ cao hơn
  useEffect(() => {
    if (!sessionId || isLinked) return;

    const checkPhoto = async () => {
      setPollCount(prev => prev + 1);
      try {
        // Gọi API lấy ảnh theo ID session
        const photo = await getPhotoById(sessionId);

        if (photo && photo.dataUrl && photo.dataUrl.length > 100) {
          console.log("Photo received from mobile!");
          setIsLinked(true);
          if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);

          // Chuyển dữ liệu về máy chủ sau hiệu ứng chúc mừng
          setTimeout(() => {
            onPhotoReceived(photo.dataUrl);
          }, 1000);
        }
      } catch (e) {
        console.warn("Polling error (Retrying...):", e);
      }
    };

    // Kiểm tra mỗi 2 giây để cân bằng giữa tốc độ và giới hạn API
    pollIntervalRef.current = setInterval(checkPhoto, 2000);
    return () => { if (pollIntervalRef.current) clearInterval(pollIntervalRef.current); };
  }, [sessionId, isLinked, onPhotoReceived]);

  return (
    <div className="absolute inset-0 z-[60] bg-slate-900/95 backdrop-blur-md flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full relative overflow-hidden ring-1 ring-white/10">
        <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-brand-500 via-purple-500 to-brand-500 animate-[shimmer_2s_infinite]"></div>

        {isLinked ? (
            <div className="py-10 animate-scaleUp">
                <div className="w-24 h-24 bg-green-500 text-white rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg shadow-green-500/40">
                    <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"></path></svg>
                </div>
                <h2 className="text-3xl font-black text-gray-800 dark:text-white uppercase tracking-tight">{t('mobile.connected', config)}</h2>
                <p className="text-gray-500 dark:text-gray-400 mt-3 font-medium">Chuẩn bị chỉnh sửa ảnh...</p>
            </div>
        ) : (
            <>
                <div className="flex justify-between items-center mb-6">
                    <div className="text-left">
                        <h2 className="text-2xl font-black text-gray-800 dark:text-white leading-tight uppercase">{t('mobile.title', config)}</h2>
                        <div className="flex items-center gap-2 mt-1">
                            <span className="w-2 h-2 bg-brand-500 rounded-full animate-ping"></span>
                            <span className="text-[10px] font-black text-brand-600 uppercase tracking-widest">Sẵn sàng kết nối</span>
                        </div>
                    </div>
                    <div className="bg-brand-50 dark:bg-brand-900/30 px-3 py-1 rounded-lg">
                        <span className="text-[10px] font-bold text-brand-600">{selectedSize.toUpperCase()}</span>
                    </div>
                </div>

                <div className="relative mx-auto w-64 h-64 mb-8 bg-white p-4 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700 group transition-transform hover:scale-[1.02]">
                    {qrUrl ? (
                        <img src={qrUrl} alt="Scan to Link" className="w-full h-full object-contain" />
                    ) : (
                        <div className="w-full h-full flex items-center justify-center">
                            <div className="w-10 h-10 border-4 border-gray-200 border-t-brand-500 rounded-full animate-spin"></div>
                        </div>
                    )}
                    <div className="absolute inset-0 bg-brand-500/5 h-1.5 w-full animate-[scan_2s_ease-in-out_infinite] pointer-events-none rounded-full"></div>
                </div>

                <p className="text-sm text-gray-500 dark:text-gray-400 mb-8 px-4 leading-relaxed">
                    Mở camera trên điện thoại và quét mã để bắt đầu chụp ảnh từ xa.
                </p>

                <div className="flex flex-col gap-4">
                    <button 
                        onClick={onCancel}
                        className="w-full py-4 bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 rounded-2xl font-bold text-sm transition-all hover:bg-red-50 hover:text-red-600 dark:hover:bg-red-900/20 active:scale-95 border border-transparent hover:border-red-100 uppercase tracking-widest"
                    >
                        Hủy & Dùng Webcam
                    </button>
                    <div className="text-[9px] text-gray-400 font-medium uppercase tracking-widest">
                        Checking Status: {pollCount}
                    </div>
                </div>
            </>
        )}
      </div>

      <style>{`
        @keyframes scan { 0% { top: 10%; opacity: 0; } 50% { opacity: 1; } 100% { top: 90%; opacity: 0; } }
        @keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }
        @keyframes scaleUp { from { transform: scale(0.9); opacity: 0; } to { transform: scale(1); opacity: 1; } }
        .animate-scaleUp { animation: scaleUp 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

