const getScriptUrl = () => {
    const config = getConfig();
    return (config.googleScriptUrl || '').trim();
};

/**
 * Hàm gọi API chung (Universal Fetch Wrapper)
 */
const callAppsScript = async (action: string, payload: any = {}): Promise<any> => {
    const url = getScriptUrl();
    if (!url) throw new Error("Chưa cấu hình Google Script URL trong Admin.");

    const fullPayload = {
        action,
        ...payload,
        _timestamp: Date.now() // Force no-cache on server-side logic
    };

    try {
        const response = await fetch(url, {
            method: 'POST',
            mode: 'no-cors', // Dùng no-cors để bypass OPTIONS request nếu cần, nhưng POST text/plain là chuẩn nhất
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(fullPayload)
        });

        // Vì Apps Script trả về redirect hoặc kết quả JSON, 
        // ở chế độ 'no-cors' chúng ta không đọc được body trực tiếp.
        // Tuy nhiên ứng dụng của chúng ta cần đọc JSON nên ta dùng mặc định:

        const normalResponse = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(fullPayload)
        });

        if (!normalResponse.ok) {
            throw new Error(`Server responded with ${normalResponse.status}`);
        }

        const data = await normalResponse.json();
        return data;

    } catch (error) {
        console.error(`API Call Error [${action}]:`, error);
        throw error;
    }
};

