                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase">Đã nhận ảnh!</h2>
                <p className="text-gray-500 dark:text-gray-400 mt-2 font-medium italic">Đang tải vào trình chỉnh sửa...</p>
            </div>
        ) : (
            <>
                <div className="flex justify-between items-center mb-6">
                    <div className="text-left">
                        <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase leading-tight">Chụp từ điện thoại</h2>
                        <div className="flex items-center gap-1.5 mt-1">
