interface MobileCameraLinkProps {
  onPhotoReceived: (dataUrl: string) => void;
  onCancel: () => void;
  config: AppConfig;
  selectedSize: PhotoSize;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ onPhotoReceived, onCancel, config, selectedSize }) => {
  const [sessionId, setSessionId] = useState<string>('');
  const [qrUrl, setQrUrl] = useState<string>('');
  const [isLinked, setIsLinked] = useState(false);
  const [pollCount, setPollCount] = useState(0);
  const pollIntervalRef = useRef<any>(null);

  useEffect(() => {
    const sid = `mob_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
    setSessionId(sid);
    return () => { if (pollIntervalRef.current) clearInterval(pollIntervalRef.current); };
  }, []);

  useEffect(() => {
    if (!sessionId) return;
    const baseUrl = window.location.href.split('?')[0];
    const mobileLink = `${baseUrl}?mobileSession=${sessionId}&size=${selectedSize}`;
    setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(mobileLink)}&color=000000&bgcolor=FFFFFF&margin=2&ecc=M`);
  }, [sessionId, selectedSize]);

  useEffect(() => {
    if (!sessionId || isLinked) return;

    const checkPhoto = async () => {
      setPollCount(prev => prev + 1);
      try {
        // Gọi API lấy ảnh theo Session ID
        const photo = await getPhotoById(sessionId);

        if (photo && photo.dataUrl && photo.dataUrl.length > 500) {
          setIsLinked(true);
          if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
          onPhotoReceived(photo.dataUrl);
        }
      } catch (e) {
        // Tiếp tục thử lại nếu lỗi mạng
      }
    };

    // Polling mỗi 1 giây để đảm bảo tốc độ phản hồi
    pollIntervalRef.current = setInterval(checkPhoto, 1000);
    return () => { if (pollIntervalRef.current) clearInterval(pollIntervalRef.current); };
  }, [sessionId, isLinked, onPhotoReceived]);

  return (
    <div className="absolute inset-0 z-[60] bg-slate-900/90 backdrop-blur-lg flex flex-col items-center justify-center p-6 text-center animate-fadeIn">
      <div className="bg-white dark:bg-gray-800 p-8 rounded-[2.5rem] shadow-2xl max-w-md w-full relative ring-1 ring-white/10">
        <div className="absolute top-0 left-0 w-full h-1.5 bg-brand-500 rounded-t-full"></div>

        {isLinked ? (
            <div className="py-10 animate-pulse">
                <div className="w-20 h-20 bg-green-500 text-white rounded-full flex items-center justify-center mx-auto mb-6 shadow-lg shadow-green-500/30">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="4" d="M5 13l4 4L19 7"></path></svg>
                </div>
                <h2 className="text-2xl font-black text-gray-800 dark:text-white uppercase">Đã nhận ảnh!</h2>
                <p className="text-gray-500 dark:text-gray-400 mt-2 font-medium italic">Đang tải vào trình chỉnh sửa...</p>
            </div>
        ) : (
            <>
                <div className="flex justify-between items-center mb-6">
                    <div className="text-left">
                        <h2 className="text-xl font-black text-gray-800 dark:text-white uppercase leading-tight">Chụp từ điện thoại</h2>
                        <div className="flex items-center gap-1.5 mt-1">
