### Bước 2: Bạn CẦN thay đổi mã trong Google Apps Script
Để Frontend có thể đọc được dữ liệu, mã Google Apps Script của bạn phải được viết chính xác như sau (Copy và thay thế toàn bộ mã cũ):

```javascript
/**
 * TOÀN BỘ MÃ GOOGLE APPS SCRIPT CHUẨN CHO PHOTO BOOTH
 * Copy đoạn này vào https://script.google.com/
 */

function doPost(e) {
  var props = PropertiesService.getScriptProperties();
  var result = { success: false };

  try {
    var data = JSON.parse(e.postData.contents);
    var action = data.action;

    if (action === 'savePhoto') {
      var id = data.id || ('photo_' + new Date().getTime());
      var photoObj = {
        id: id,
        dataUrl: data.dataUrl,
        settings: data.settings,
        timestamp: new Date().getTime()
      };
      // Lưu vào ScriptProperties (Giới hạn 9KB/key, nếu ảnh lớn cần dùng CacheService hoặc Drive)
      // Với ảnh Base64 lớn, ta dùng CacheService làm bộ đệm trung gian cho Session nhanh
      var cache = CacheService.getScriptCache();
      cache.put(id, JSON.stringify(photoObj), 600); // Lưu trong 10 phút

      // Đồng thời lưu ID vào danh sách chung (optional)
      result.success = true;
      result.id = id;
    } 

    else if (action === 'getPhoto') {
      var id = data.id;
      var cache = CacheService.getScriptCache();
      var cached = cache.get(id);

      if (cached) {
        result.success = true;
        result.photo = JSON.parse(cached);
      } else {
        result.success = false;
        result.error = "Not found";
      }
    }

    else if (action === 'saveConfig') {
      props.setProperty('app_config', JSON.stringify(data.config));
      result.success = true;
    }

    else if (action === 'getConfig') {
      var config = props.getProperty('app_config');
      result.success = true;
      result.config = config ? JSON.parse(config) : null;
    }

  } catch (error) {
    result.error = error.toString();
  }

  // QUAN TRỌNG: Trả về header JSON chuẩn để Frontend đọc được
  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

// Cho phép truy cập qua trình duyệt nếu cần test
function doGet(e) {
  return ContentService.createTextOutput("Photo Booth API is running.");
}
```

**Sau khi thay mã Script:**
1. Nhấn **Deploy** (Triển khai) -> **New Deployment** (Triển khai mới).
2. Chọn loại: **Web App**.
3. **Execute as:** Me (Tôi).
4. **Who has access:** Anyone (Bất kỳ ai).
5. Copy đường link mới nhận được và dán vào phần **Admin Dashboard -> Cloud Sync URL** trong ứng dụng của bạn.

Việc dùng `CacheService` trong Apps Script như đoạn mã trên sẽ giúp ảnh được truyền từ Điện thoại sang Máy tính gần như tức thời (dưới 1 giây).

