  let config = { ...DEFAULT_CONFIG };

  if (saved) {
    try {
      const parsed = JSON.parse(saved);
      // Merge items carefully to ensure new arrays exist if older config is used
      config = { ...DEFAULT_CONFIG, ...parsed };
    } catch (e) {}
  }

  // Ensure script URL isn't accidentally cleared if it was hardcoded but you may want to allow editing
  return config;
};

const hexToRgb = (hex: string) => {
  let r = 0, g = 0, b = 0;
  if (hex.length === 4) {
    r = parseInt("0x" + hex[1] + hex[1]);
    g = parseInt("0x" + hex[2] + hex[2]);
    b = parseInt("0x" + hex[3] + hex[3]);
  } else if (hex.length === 7) {
    r = parseInt("0x" + hex[1] + hex[2]);
    g = parseInt("0x" + hex[3] + hex[4]);
    b = parseInt("0x" + hex[5] + hex[6]);
  }
  return `${r} ${g} ${b}`;
};

export const applyTheme = (hexColor: string) => {
  if (!hexColor) return;
  const rgb = hexToRgb(hexColor);
  const root = document.documentElement;
  root.style.setProperty('--brand-500', rgb);
  root.style.setProperty('--brand-600', rgb);
  root.style.setProperty('--brand-700', rgb);
  root.style.setProperty('--brand-50', rgb);
  root.style.setProperty('--brand-100', rgb);
  root.style.setProperty('--brand-200', rgb);
};

export const applyThemeMode = (mode: 'light' | 'dark' | 'system') => {
  const root = document.documentElement;

  if (mode === 'dark') {
    root.classList.add('dark');
  } else if (mode === 'light') {
    root.classList.remove('dark');
  } else {
    // System
    if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }
};

export const updateFavicon = (logoUrl?: string) => {
  const link = document.getElementById('dynamic-favicon') as HTMLLinkElement;
  if (link) {
    link.href = logoUrl || "data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>📸</text></svg>";
  }
};

import { SavedPhoto, AppConfig } from "../types";
import { getConfig } from "./configService";

const getScriptUrl = () => {
    const config = getConfig();
    return (config.googleScriptUrl || '').trim();
};

const callAppsScript = async (action: string, payload: any = {}): Promise<any> => {
    const url = getScriptUrl();
    if (!url) return { success: false, error: "Missing URL" };

    const fullPayload = {
        action,
        ...payload,
        _timestamp: Date.now()
    };

    try {
        const response = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'text/plain;charset=utf-8' },
            body: JSON.stringify(fullPayload)
        });

        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return await response.json();
    } catch (error) {
        console.error(`Apps Script Error [${action}]:`, error);
        return { success: false, error: String(error) };
    }
};

export const savePhotoToCloud = async (photo: SavedPhoto): Promise<string | null> => {
    const result = await callAppsScript('savePhoto', {
        id: photo.id,
        dataUrl: photo.dataUrl,
        settings: photo.settings
    });
    return (result && result.success) ? result.id : null;
};

export const getPhotoById = async (id: string): Promise<SavedPhoto | null> => {
    const result = await callAppsScript('getPhoto', { id });
    if (result && result.success && result.photo) {
        return result.photo as SavedPhoto;
    }
    return null;
};

export const saveAppConfigToCloud = async (config: AppConfig): Promise<boolean> => {
    const result = await callAppsScript('saveConfig', { config });
    return !!(result && result.success);
};

export const getAppConfigFromCloud = async (): Promise<AppConfig | null> => {
    const result = await callAppsScript('getConfig');
    return (result && result.success) ? result.config : null;
};

export const getPhotosFromCloud = async (): Promise<SavedPhoto[]> => {
    const result = await callAppsScript('listPhotos');
    return (result && result.success && Array.isArray(result.photos)) ? result.photos : [];
};

export const deletePhotoFromCloud = async (id: string, adminPassword?: string): Promise<boolean> => {
    const result = await callAppsScript('deletePhoto', { id, password: adminPassword });
    return !!(result && result.success);
};

import React, { useRef, useState, useEffect, useCallback, useMemo } from 'react';
import { PhotoSize, AppConfig } from '../types';
import { analyzeIDPhotoFrame } from '../services/geminiService';
import { savePhotoToCloud } from '../services/databaseService';
import { t } from '../services/i18n';

interface MobileCaptureClientProps {
  sessionId: string;
  config: AppConfig;
  initialSize?: PhotoSize;
}

type ValidationStatus = 'searching' | 'analyzing' | 'adjusting' | 'valid';

const SHUTTER_SOUND = "data:audio/mp3;base64,";

const MobileCaptureClient: React.FC<MobileCaptureClientProps> = ({ sessionId, config, initialSize = PhotoSize.SIZE_4X6 }) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const analysisCanvasRef = useRef<HTMLCanvasElement>(null);
  const shutterAudioRef = useRef<HTMLAudioElement | null>(null);
  const analysisIntervalRef = useRef<any>(null);
  const isAnalyzingRef = useRef(false);
  const lastSpokenRef = useRef<string>('');
  const hasAutoCapturedRef = useRef(false);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [capturedImage, setCapturedImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [isCompleted, setIsCompleted] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);
  const [validationStatus, setValidationStatus] = useState<ValidationStatus>('searching');
  const [feedbackMessage, setFeedbackMessage] = useState<string>(t('capture.label.processing', config));
  const [instruction, setInstruction] = useState<string>('');
  const [cameraError, setCameraError] = useState('');
  const [facingMode, setFacingMode] = useState<'user' | 'environment'>('user');
  const [isAutoCaptureEnabled, setIsAutoCaptureEnabled] = useState(true);

  const startCamera = async (mode: 'user' | 'environment') => {
    if (stream) stream.getTracks().forEach(track => track.stop());
    const constraints: MediaStreamConstraints = { video: { facingMode: mode, width: { ideal: 1920 }, height: { ideal: 1080 } } };
    try {
      const s = await navigator.mediaDevices.getUserMedia(constraints);
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
    } catch (e) {
      setCameraError('Máy ảnh chưa được cấp quyền.');
    }
  };

  useEffect(() => {
    startCamera(facingMode);
    shutterAudioRef.current = new Audio(SHUTTER_SOUND);
    return () => {
      if (stream) stream.getTracks().forEach(t => t.stop());
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    };
  }, [facingMode]);

  useEffect(() => {
    if (stream && !countdown && !capturedImage) {
      analysisIntervalRef.current = setInterval(performAIAnalysis, 3000);
    } else {
      if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current);
    }
    return () => { if (analysisIntervalRef.current) clearInterval(analysisIntervalRef.current); };
  }, [stream, countdown, capturedImage]);

  useEffect(() => {
    if (isAutoCaptureEnabled && validationStatus === 'valid' && !hasAutoCapturedRef.current && countdown === null && !capturedImage) {
      hasAutoCapturedRef.current = true;
      setCountdown(3);
    } else if (validationStatus !== 'valid') {
      hasAutoCapturedRef.current = false;
    }
  }, [validationStatus, isAutoCaptureEnabled, countdown, capturedImage]);

  const performAIAnalysis = async () => {
    if (isAnalyzingRef.current || !videoRef.current || !analysisCanvasRef.current) return;
    try {
      isAnalyzingRef.current = true;
      const video = videoRef.current;
      const canvas = analysisCanvasRef.current;
      const ctx = canvas.getContext('2d');
      if (video.readyState === 4 && ctx) {
        const crop = getCropDimensions(video.videoWidth, video.videoHeight);
        canvas.width = 240; canvas.height = 360;
        if (facingMode === 'user') { ctx.translate(canvas.width, 0); ctx.scale(-1, 1); }
        ctx.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
        const result = await analyzeIDPhotoFrame(canvas.toDataURL('image/jpeg', 0.5));
        if (!result.faceDetected) {
            setValidationStatus('searching'); setFeedbackMessage(t('capture.msg.no_face', config)); setInstruction(t('capture.msg.move_in', config));
        } else if (result.isCompliant) {
            setValidationStatus('valid'); setFeedbackMessage(t('capture.status.valid', config)); setInstruction(t('capture.msg.valid', config));
        } else {
            setValidationStatus('adjusting'); setFeedbackMessage(result.feedback || t('capture.status.adjusting', config)); setInstruction(result.instruction || '');
        }
      }
    } catch (err) {} finally { isAnalyzingRef.current = false; }
  };

  const getCropDimensions = (sourceW: number, sourceH: number) => {
    let targetRatio = initialSize === PhotoSize.SIZE_5X5 ? 1 : (initialSize === PhotoSize.SIZE_3X4 ? 3/4 : 2/3);
    const sourceRatio = sourceW / sourceH;
    let cropW, cropH, startX, startY;
    if (sourceRatio > targetRatio) { cropH = sourceH; cropW = cropH * targetRatio; startX = (sourceW - cropW) / 2; startY = 0; }
    else { cropW = sourceW; cropH = cropW / targetRatio; startX = 0; startY = (sourceH - cropH) * 0.5; }
    return { x: Math.floor(startX), y: Math.floor(startY), w: Math.floor(cropW), h: Math.floor(cropH) };
  };

  const captureFrame = useCallback(() => {
    if (shutterAudioRef.current) shutterAudioRef.current.play().catch(() => {});
    if (!videoRef.current || !canvasRef.current) return;
    const video = videoRef.current;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const crop = getCropDimensions(video.videoWidth, video.videoHeight);
    // Lưu độ phân giải cao để in ấn nhưng nén JPG để đồng bộ nhanh
    canvas.width = 1200; canvas.height = Math.floor(1200 / (crop.w/crop.h));
    if (facingMode === 'user') { ctx?.translate(canvas.width, 0); ctx?.scale(-1, 1); }
    ctx?.drawImage(video, crop.x, crop.y, crop.w, crop.h, 0, 0, canvas.width, canvas.height);
    setCapturedImage(canvas.toDataURL('image/jpeg', 0.85)); // 0.85 là mức cân bằng tốt nhất giữa dung lượng và chất lượng
  }, [facingMode, initialSize]);

  useEffect(() => {
    if (countdown === null) return;
    if (countdown > 0) {
        const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
        return () => clearTimeout(timer);
    } else {
        captureFrame();
        setCountdown(null);
    }
  }, [countdown, captureFrame]);

  const handleUpload = async () => {
    if (!capturedImage || !sessionId) return;
    setIsUploading(true);
    try {
        const resultId = await savePhotoToCloud({
            id: sessionId,
            dataUrl: capturedImage,
            timestamp: Date.now(),
            settings: { size: initialSize, background: 'original' as any, beauty: {} as any, printQuantity: 1 }
        });
        if (resultId) setIsCompleted(true);
        else alert('Đồng bộ thất bại. Vui lòng thử lại.');
    } catch (e) { 
        alert('Lỗi kết nối Cloud.'); 
    } finally { 
        setIsUploading(false); 
    }
  };

  const topMarginPercent = useMemo(() => initialSize === PhotoSize.SIZE_3X4 ? 7.5 : initialSize === PhotoSize.SIZE_5X5 ? 6 : 7, [initialSize]);
  const overlayColor = validationStatus === 'valid' ? '#22c55e' : validationStatus === 'adjusting' ? '#facc15' : '#ef4444';

  if (isCompleted) {
    return (
        <div className="h-[100dvh] bg-brand-600 flex flex-col items-center justify-center text-white p-8 text-center animate-fadeIn">
            <div className="w-20 h-20 bg-white rounded-full flex items-center justify-center mb-8 shadow-2xl">
                <svg className="w-10 h-10 text-brand-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M5 13l4 4L19 7"></path></svg>
            </div>
            <h2 className="text-2xl font-black mb-4 uppercase">Gửi thành công!</h2>
            <p className="opacity-90">Hãy quay lại màn hình máy tính để chỉnh sửa ảnh.</p>
        </div>
    );
  }

  return (
    <div className="h-[100dvh] bg-black flex flex-col relative overflow-hidden touch-none py-safe">
        <div className="absolute top-0 left-0 right-0 p-4 z-50 flex flex-col items-center pointer-events-none">
            {!capturedImage && (
                <div className={`px-6 py-2 rounded-full backdrop-blur-md border-2 transition-all duration-300 text-center shadow-lg flex flex-col ${validationStatus === 'valid' ? 'bg-green-600/90 border-green-400' : 'bg-black/60 border-white/20'}`}>
                    <span className="text-white font-black text-xs uppercase tracking-widest">{feedbackMessage}</span>
                    <span className="text-white/80 text-[10px]">{instruction}</span>
                </div>
            )}
        </div>

        <div className="flex-1 relative flex items-center justify-center bg-gray-900 overflow-hidden">
            {cameraError ? (
                <div className="text-white text-center p-6 bg-black/80 rounded-2xl border border-red-500 m-4">
                    <p className="font-bold">{cameraError}</p>
                    <button onClick={() => window.location.reload()} className="mt-4 px-6 py-2 bg-white text-black rounded-full font-bold">Thử lại</button>
                </div>
            ) : capturedImage ? (
                <div className="relative h-full w-full flex items-center justify-center p-4">
                    <img src={capturedImage} className="max-h-full max-w-full rounded shadow-2xl" alt="Preview" />
                </div>
            ) : (
                <>
                    <video ref={videoRef} autoPlay playsInline className={`absolute inset-0 w-full h-full object-cover ${facingMode === 'user' ? 'transform -scale-x-100' : ''}`} />
                    <svg viewBox="0 0 100 100" className="absolute inset-0 w-full h-full opacity-90 pointer-events-none z-20">
                        <defs><mask id="m"><rect x="0" y="0" width="100" height="100" fill="white" /><ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="black" /></mask></defs>
                        <rect x="0" y="0" width="100" height="100" fill="rgba(0,0,0,0.6)" mask="url(#m)" />
                        <ellipse cx="50" cy={topMarginPercent + 35} rx={32} ry={38} fill="none" stroke={overlayColor} strokeWidth="0.5" strokeDasharray="2,2" />
                    </svg>
                </>
            )}

            {countdown !== null && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 z-[100] backdrop-blur-sm">
                    <span className="text-8xl font-black text-white animate-ping">{countdown}</span>
                </div>
