      <content><![CDATA[// Add enhanced logging to databaseService.ts
import { BASE_URL } from '../config';

export async function savePhotoToCloud(photoData: string, fileName: string): Promise<string | null> {
  const url = `${BASE_URL}/upload`;
  const options: RequestInit = {
    method: 'POST',
    headers: {
      'Content-Type': 'text/plain', // Crucial for CORS and data transfer
    },
    body: photoData,
  };

  try {
    const response = await fetch(url, options);
    const data = await response.json();
    console.log('Server response:', data); // Log the server's response
    if (response.ok && data.success) {
      console.log('Photo upload success:', data.photoId); // Log the photo ID if successful
      return data.photoId;
    } else {
      console.error('Photo upload failed:', data.error || 'Unknown error'); // Log the error if the server indicates a failure
      return null;
    }
  } catch (error) {
    console.error('Fetch error:', error); // Log any fetch-related errors
    return null;
  }
}

export async function getPhotoById(photoId: string): Promise<string | null> {
  const url = `${BASE_URL}/getPhoto?id=${photoId}`;
  try {
    const response = await fetch(url);
    if (!response.ok) {
      console.error(`HTTP error! status: ${response.status}`);
      return null;
    }
    const blob = await response.blob();
    const reader = new FileReader();
    return new Promise<string | null>((resolve) => {
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = () => {
        console.error('Error reading blob.');
        resolve(null);
      };
      reader.readAsDataURL(blob);
    });
  } catch (error) {
    console.error('Fetch error during photo retrieval:', error);
    return null;
  }
}
]]></content>
