      <content><![CDATA[// Updated MobileCameraLink.tsx with a status indicator for debugging
import React, { useState, useEffect } from 'react';
import { getPhotoById } from '../services/databaseService';

interface MobileCameraLinkProps {
  photoId: string | null;
}

const MobileCameraLink: React.FC<MobileCameraLinkProps> = ({ photoId }) => {
  const [photoData, setPhotoData] = useState<string | null>(null);
  const [attempts, setAttempts] = useState(0);
  const [status, setStatus] = useState<string>('Waiting for image...');
  const MAX_ATTEMPTS = 10;
  const POLL_INTERVAL = 1000; // 1 second

  useEffect(() => {
    let intervalId: NodeJS.Timeout | null = null;

    const fetchData = async () => {
      if (photoId) {
        setAttempts(prev => prev + 1);
        setStatus(`Attempt ${attempts + 1}/${MAX_ATTEMPTS}...`);

        const data = await getPhotoById(photoId);
        if (data) {
          setPhotoData(data);
          setStatus('Image loaded!');
          clearInterval(intervalId!);
