### 1. CẬP NHẬT MÃ GOOGLE APPS SCRIPT (PHIÊN BẢN V6 - TỐI ƯU HÓA THƯ MỤC)

Mã này sẽ tự động tạo và quản lý duy nhất **một thư mục** trên Google Drive của bạn. Nó sử dụng "ID Thư Mục" để truy cập trực tiếp, giúp tốc độ nhanh hơn và không bao giờ bị lạc ảnh.

**Vui lòng copy mã này vào Apps Script và Deploy lại:**

```javascript
/**
 * GOOGLE APPS SCRIPT V6 - UNIFIED STORAGE ENGINE
 * Gom tất cả ảnh vào một thư mục cố định và truy xuất siêu tốc.
 */

function getFolder() {
  var props = PropertiesService.getScriptProperties();
  var folderId = props.getProperty("MAIN_FOLDER_ID");
  var folder;

  if (folderId) {
    try {
      folder = DriveApp.getFolderById(folderId);
    } catch (e) {
      folder = null; // Folder bị xóa hoặc không quyền truy cập
    }
  }

  if (!folder) {
    var folderName = "ID_PHOTO_BOOTH_GALLERY";
    var folders = DriveApp.getFoldersByName(folderName);
    folder = folders.hasNext() ? folders.next() : DriveApp.createFolder(folderName);
    props.setProperty("MAIN_FOLDER_ID", folder.getId());
  }
  return folder;
}

function doPost(e) {
  var result = { success: false };
  var props = PropertiesService.getScriptProperties();

  try {
    var data = JSON.parse(e.postData.contents);
    var action = data.action;

    if (action === 'savePhoto') {
      var folder = getFolder();
      var photoObj = {
        id: data.id,
        dataUrl: data.dataUrl,
        settings: data.settings,
        timestamp: new Date().getTime()
      };

      // Tạo file JSON lưu trữ
      var file = folder.createFile("PHOTO_" + data.id + ".json", JSON.stringify(photoObj));

      // Ánh xạ ID phiên với ID file để máy tính tìm thấy ngay lập tức
      props.setProperty("MAP_" + data.id, file.getId());

      result.success = true;
      result.id = data.id;
    } 

    else if (action === 'getPhoto') {
      var fileId = props.getProperty("MAP_" + data.id);
      if (fileId) {
        var file = DriveApp.getFileById(fileId);
        result.photo = JSON.parse(file.getBlob().getDataAsString());
        result.success = true;
      }
    }

    else if (action === 'listPhotos') {
      var folder = getFolder();
      var files = folder.getFiles();
      var photos = [];
      var count = 0;
      while (files.hasNext() && count < 50) { // Giới hạn 50 ảnh mới nhất
        var file = files.next();
        if (file.getName().indexOf("PHOTO_") === 0) {
          try {
            photos.push(JSON.parse(file.getBlob().getDataAsString()));
            count++;
          } catch(e) {}
        }
      }
      // Sắp xếp theo thời gian mới nhất
      photos.sort(function(a, b) { return b.timestamp - a.timestamp; });
      result.photos = photos;
      result.success = true;
    }

    else if (action === 'deletePhoto') {
      var fileId = props.getProperty("MAP_" + data.id);
      if (fileId) {
        DriveApp.getFileById(fileId).setTrashed(true);
        props.deleteProperty("MAP_" + data.id);
      }
      result.success = true;
    }

    else if (action === 'saveConfig') {
      props.setProperty('app_config', JSON.stringify(data.config));
      result.success = true;
    }

    else if (action === 'getConfig') {
      var config = props.getProperty('app_config');
      result.success = true;
      result.config = config ? JSON.parse(config) : null;
    }

  } catch (error) {
    result.error = error.toString();
  }

  return ContentService.createTextOutput(JSON.stringify(result))
    .setMimeType(ContentService.MimeType.JSON);
}

function doGet() {
  return ContentService.createTextOutput("Sync Engine V6 - Unified Folder Mode.");
}
